    { id=20830, tab=2, tier=2, col=2, name="Pyroblast", icon="spell_fire_fireball02", maxRank=1, prereqTalent=0, prereqPoints=10, wired=true, tooltip={ "Hurls an immense fiery boulder that causes 148 to 195 Fire damage and an additional 56 Fire damage over 12 sec." }, grant={ [1]=948870 }, localized={deDE={name="Pyroschlag", tooltip={ "Schleudert einen riesigen feurigen Felsbrocken, der 148 bis 195 Feuerschaden sowie zusätzlich 56 Feuerschaden im Verlauf von 12 Sek. verursacht." }}} },
    { id=20831, tab=2, tier=2, col=3, name="Burning Soul", icon="spell_fire_fire", maxRank=2, prereqTalent=0, prereqPoints=10, wired=true, tooltip={ "Gives your Fire spells a 35% chance to not lose casting time when you take damage and reduces the threat caused by your Fire spells by 5%.", "Gives your Fire spells a 70% chance to not lose casting time when you take damage and reduces the threat caused by your Fire spells by 10%." }, localized={deDE={name="Brennende Seele", tooltip={ "Gewährt Euren Feuerzaubern eine Chance von 35%, bei erlittenem Schaden keine Zauberzeit zu verlieren, und verringert die von Euren Feuerzaubern erzeugte Bedrohung um 5%.", "Gewährt Euren Feuerzaubern eine Chance von 70%, bei erlittenem Schaden keine Zauberzeit zu verlieren, und verringert die von Euren Feuerzaubern erzeugte Bedrohung um 10%." }}} },
