    { id=20833, tab=2, tier=3, col=1, name="Molten Shields", icon="spell_fire_firearmor", maxRank=2, prereqTalent=0, prereqPoints=15, wired=true, tooltip={ "Causes your Fire Ward to have a 10% chance to reflect Fire spells while active. In addition, your Molten Armor has a 50% chance to affect ranged and spell attacks.", "Causes your Fire Ward to have a 20% chance to reflect Fire spells while active. In addition, your Molten Armor has a 100% chance to affect ranged and spell attacks." }, localized={deDE={name="Glühende Schilde", tooltip={ "Gewährt Eurem 'Feuerzauberschutz' während seiner Wirkungsdauer eine Chance von 10%, Feuerzauber zu reflektieren. Außerdem hat Eure 'Glühende Rüstung' eine Chance von 50%, auch bei Fernkampf- und Zauberangriffen zu wirken.", "Gewährt Eurem 'Feuerzauberschutz' während seiner Wirkungsdauer eine Chance von 20%, Feuerzauber zu reflektieren. Außerdem hat Eure 'Glühende Rüstung' eine Chance von 100%, auch bei Fernkampf- und Zauberangriffen zu wirken." }}} },
